-- Insert Quiz Questions for Lesson: Sites, Forms, Funnels, and Lead Capture

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'sites-forms-funnels' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson sites-forms-funnels not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How do people enter LeadProspectrr?', 
    '["Only by phone call","Through websites, funnels, landing pages, forms, surveys, chat widgets, and calendars","Only by email","They cannot enter the system"]'::jsonb,
    'Through websites, funnels, landing pages, forms, surveys, chat widgets, and calendars',
    'People enter LeadProspectrr through multiple channels: websites, funnels, landing pages, forms, surveys, chat widgets, and calendar bookings.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the key idea about pages and funnels?', 
    '["The page design is everything","The page is just the beginning; the value comes from what happens after the visitor takes action","Pages should have no follow-up","Only beautiful pages work"]'::jsonb,
    'The page is just the beginning; the value comes from what happens after the visitor takes action',
    'The page or funnel is just the entry point. The real value comes from the follow-up: contact creation, tagging, workflows, notifications, and nurture sequences.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What happens in a typical lead journey?', 
    '["Visitor lands on page and nothing else happens","Visitor completes form, contact created, tag added, workflow begins, confirmation sent, appointment booked, opportunity created","Visitor is automatically deleted","Visitor receives spam"]'::jsonb,
    'Visitor completes form, contact created, tag added, workflow begins, confirmation sent, appointment booked, opportunity created',
    'A typical lead journey includes: landing on page, completing form, contact creation, tagging, workflow trigger, confirmation email, appointment booking, and opportunity creation.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
